    /// Ray casting per ring: inside when a ray east of the point crosses a ring's edge an odd number of times. A longitude east of
    /// 180° (an iPhone on Attu reports +173) is unwrapped first.
    static func contains(_ c: CLLocationCoordinate2D) -> Bool {
        let lon = c.longitude > 0 ? c.longitude - 360 : c.longitude
        for ring in rings {
            var inside = false
            var j = ring.count - 1
            for i in 0..<ring.count {
                let (xi, yi) = ring[i], (xj, yj) = ring[j]
                if (yi > c.latitude) != (yj > c.latitude) && lon < (xj - xi) * (c.latitude - yi) / (yj - yi) + xi { inside.toggle() }
                j = i
            }
            if inside { return true }
        }
        return false
    }
